  pepozhen: {
    audio: 2,
    persevereSkill: true,
    forced: true,
    locked: false,
    trigger: { source: "damageSource" },
    filter(event, player) {
      const target = event.player;
      if (player === target || !target?.isIn()) {
        return false;
      }
      if (!target.getStorage("pepozhen_used").includes("选项一") && !player.getStorage("pepozhen_use").includes(target)) {
        return true;
      }
      if (!target.getStorage("pepozhen_used").includes("选项二") && target.hasGainableCards(player, "hej")) {
        return true;
      }
      if (!target.getStorage("pepozhen_used").includes("选项三")) {
        return true;
      }
      return false;
    },
    logTarget: "player",
    async content(event, trigger, player) {
      const target = trigger.player;
      const list = [];
      const choiceList = [`令${get.translation(player)}对你使用牌无距离次数限制`, `交给${get.translation(player)}一个区域内的所有牌`, "体力上限调整为1且失去所有技能"];
      if (!target.getStorage("pepozhen_used").includes("选项一") && !player.getStorage("pepozhen_use").includes(target)) {
        list.push("选项一");
      } else {
        choiceList[0] = `<span style="opacity:0.5">${choiceList[0]}</span>`;
      }
      if (!target.getStorage("pepozhen_used").includes("选项二") && target.hasGainableCards(player, "hej")) {
        list.push("选项二");
      } else {
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}</span>`;
      }
      if (!target.getStorage("pepozhen_used").includes("选项三")) {
        list.push("选项三");
      } else {
        choiceList[2] = `<span style="opacity:0.5">${choiceList[2]}</span>`;
      }
      if (list.length) {
        let result;
        result = list.length > 1 ? await target.chooseControl({
          prompt: `${get.translation(player)}对你发动了【破阵】，请选择一项`,
          choiceList,
          controls: list,
          ai() {
            const { controls, player: player2, source } = get.event();
            if (get.attitude(player2, source) > 0) {
              if (controls.includes("选项二")) {
                return "选项二";
              } else if (controls.includes("选项一")) {
                return "选项一";
              }
            }
            if (controls.includes("选项一")) {
              return "选项一";
            } else if (controls.includes("选项二")) {
              return "选项二";
            }
            return controls.slice(0).randomGet();
          }
        }).set("source", player).forResult() : { control: list[0] };
        if (typeof result?.control === "string") {
          const control = result.control;
          target.addTempSkill(`${event.name}_used`);
          target.markAuto(`${event.name}_used`, [control]);
          if (control === "选项一") {
            player.addSkill(`${event.name}_use`);
            player.markAuto(`${event.name}_use`, [target]);
          } else if (control === "选项二") {
            const map = { h: "手牌区", e: "装备区", j: "判定区" };
            const pos = ["h", "e", "j"].filter((i) => target.countGainableCards(player, i));
            if (pos.length) {
              result = pos.length > 1 ? await target.chooseControl({
                controls: pos.map((i) => map[i]),
                prompt: `选择一个区域内的所有牌交给${get.translation(player)}`,
                ai() {
                  const { player: player2, source, controls } = get.event();
                  if (get.attitude(player2, source) > 0) {
                    if (controls.includes("h") && player2.countGainableCards(source, "h") > 3) {
                      return "h";
                    }
                  }
                  if (controls.includes("j")) {
                    return "j";
                  }
                  if (controls.includes("e") && player2.countGainableCards(source, "e") < 3) {
                    return "e";
                  }
                  return controls.slice(0).randomGet();
                }
              }).set("source", player).forResult() : { control: pos[0] };
              const reverseMap = Object.fromEntries(Object.entries(map).map(([k, v]) => [v, k]));
              const cards2 = target.getGainableCards(player, reverseMap[result.control]);
              if (cards2?.length) {
                await target.give(cards2, player);
              }
            }
          } else {
            if (target.maxHp > 1) {
              await target.loseMaxHp(target.maxHp - 1);
            } else if (target.maxHp < 1) {
              await target.gainMaxHp(1 - target.maxHp);
            }
            await target.removeSkills(
              target.getSkills(null, false, false).filter((skill) => {
                const info = get.info(skill);
                return info && !info.charlotte;
              })
            );
          }
        }
      }
    },
    subSkill: {
      used: { charlotte: true, onremove: true },
      use: {
        charlotte: true,
        onremove: true,
        intro: { content: "对$使用牌无距离次数限制" },
        mod: {
          targetInRange(card, player, target) {
            if (player.getStorage("pepozhen_use").includes(target)) {
              return true;
            }
          },
          cardUsableTarget(card, player, target) {
            if (player.getStorage("pepozhen_use").includes(target)) {
              return Infinity;
            }
          }
        }
      }
    }
  },
